import {Asset} from 'expo-asset';import * as FS from 'expo-file-system/legacy';import {Platform} from 'react-native';
export const brandLogos={A:require('../assets/brand/zhongyue-A-1024.png'),B:require('../assets/brand/zhongyue-B-1024.png'),C:require('../assets/brand/zhongyue-C-1024.png')};
export const bundledBackground=require('../assets/theme/bg_default_light.jpg');
export const bundledCovers=[require('../assets/theme/cover_0.png'),require('../assets/theme/cover_1.png'),require('../assets/theme/cover_2.png'),require('../assets/theme/cover_3.png'),require('../assets/theme/cover_4.png'),require('../assets/theme/cover_5.png')];
export const bundledTabs={'书架':{normal:require('../assets/theme/tab_bookshelf.png'),selected:require('../assets/theme/sel_bookshelf.png')},'发现':{normal:require('../assets/theme/tab_explore.png'),selected:require('../assets/theme/sel_explore.png')},'书源':{normal:require('../assets/theme/tab_search.png'),selected:require('../assets/theme/sel_search.png')},'统计':{normal:require('../assets/theme/tab_stats.png'),selected:require('../assets/theme/sel_stats.png')},'设置':{normal:require('../assets/theme/tab_settings.png'),selected:require('../assets/theme/sel_settings.png')}};
const fontModule=require('../assets/fonts/ZhongXingBi-Regular.ttf');
async function localAsset(module,name,expectedSize){const asset=Asset.fromModule(module);await asset.downloadAsync();if(Platform.OS==='web')return asset.localUri||asset.uri;const dir=FS.documentDirectory+'zhongyue-bundled/';await FS.makeDirectoryAsync(dir,{intermediates:true});const target=dir+name;const info=await FS.getInfoAsync(target);if(!info.exists||expectedSize&&info.size!==expectedSize)await FS.copyAsync({from:asset.localUri||asset.uri,to:target});return target;}
export async function loadBundledTheme(){const [fontUri,imageUri,logoA,logoB,logoC]=await Promise.all([localAsset(fontModule,'ZhongXingBi-Regular.ttf',25774956),localAsset(bundledBackground,'jianjia-background.jpg'),localAsset(brandLogos.A,'logo-A.png'),localAsset(brandLogos.B,'logo-B.png'),localAsset(brandLogos.C,'logo-C.png')]);const font={name:'BundledZhongXingBi',label:'◉字美-中性笔.ttf',uri:fontUri,bundled:true};return {font,logoUris:{A:logoA,B:logoB,C:logoC},settings:{brandAssetsVersion:1,bundledThemeEnabled:true,bundledThemeName:'蒹葭苍苍',appFollowSystem:true,appDarkBackground:'#142821',appDarkInk:'#F2F2F2',darkCardColor:'#1C1C1E',accent:'#ACC897',appBackground:'#F5F5EC',uiInk:'#111111',appImage:imageUri,uiFont:true,uiFontDefinition:font,fonts:[font],tabLabels:false,forceDefaultCover:true,defaultCover:0,shelfLayout:'列表',shelfSize:146,shelfColumns:3,showTags:true,cardColor:'#FFFFFF',cardOpacity:85,borderColor:'#E5E5EA',borderOpacity:100,borderWidth:.7,cardRadius:14,glow:60,glass:true,font:null,readerStyle:'极简',flipMode:'平移',background:'#1C1C1E',ink:'#C8C8CA',lightBackground:'#F8F5ED',lightInk:'#383B36',darkBackground:'#1C1C1E',darkInk:'#C8C8CA',size:21,spacing:1.9,paragraphGap:10,indent:2,textAlign:'justify',letterSpacing:0,fontWeight:'400',marginLeft:16,marginRight:16,marginTop:16,marginBottom:20,showStatusBar:false,paragraphBubbles:true,bubbleStyle:'猫耳',readerHeaderCompact:true,showReaderClock:true,showReaderBattery:true,startupEnabled:true,startupImage:logoB,startupBuiltinLogo:true,brandLogoUris:{A:logoA,B:logoB,C:logoC}}};}
export function mergeBundledTheme(settings,bundled){const fonts=[...(settings?.fonts||[]).filter(f=>!f.bundled),bundled.font];if(!settings?.brandAssetsVersion)return {...settings,...bundled.settings,fonts,bundledPreset:bundled.settings};return {...settings,bundledPreset:bundled.settings,uiFontDefinition:bundled.font,fonts,brandLogoUris:bundled.logoUris};}
